// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate, uint128 vBase, uint128 vNft, uint56 changeFee) public {
        vm.assume(feeRate <= 5000);

        vm.assume(vBase <= type(uint128).max);
        vm.assume(vNft <= type(uint128).max);
        vm.assume(changeFee <= type(uint56).max);

        bool ok;
        try c.initialize(address(0), address(1), vBase, vNft, changeFee, feeRate, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
